import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md","lastUpdated":1786978836000}`),a={name:`guide/getting-started.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to “Getting started”">​</a></h1><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to “Requirements”">​</a></h2><ul><li><strong>Node.js 22 or newer</strong> (or Docker)</li><li><strong>Audiobookshelf 2.26.0 or newer</strong> — earlier versions have no API keys</li><li>An Audiobookshelf <strong>API key</strong></li></ul><p>Check your server version without logging in:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">curl</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> -s</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> https://abs.example.com/status</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;"> |</span><span style="--shiki-light:#953800;--shiki-dark:#FFA657;"> jq</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> .serverVersion</span></span></code></pre></div><h2 id="getting-an-api-key" tabindex="-1">Getting an API key <a class="header-anchor" href="#getting-an-api-key" aria-label="Permalink to “Getting an API key”">​</a></h2><p>API keys are managed by an admin under <strong>Settings → Users → API Keys</strong>.</p><p>A key acts on behalf of exactly one Audiobookshelf user and inherits that user&#39;s permissions. A key issued for a normal account cannot see libraries that account cannot see, and cannot delete anything unless that account may delete. That makes the choice of user the main security control you have here — see <a href="/guide/security">Security</a>.</p><div class="warning custom-block"><p class="custom-block-title">The key is shown only once</p><p>Copy it at creation time. If you lose it, delete the key and create a new one.</p></div><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to “Install”">​</a></h2><p>Nothing to install permanently — <code>npx</code> fetches the package on first run:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">claude</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> mcp</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> add</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> audiobookshelf</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;"> \\</span></span>
<span class="line"><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;">  -e</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> AUDIOBOOKSHELF_URL=https://abs.example.com</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;"> \\</span></span>
<span class="line"><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;">  -e</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> AUDIOBOOKSHELF_API_KEY=…</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;"> \\</span></span>
<span class="line"><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;">  --</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> npx</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> -y</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> audiobookshelf-mcp</span></span></code></pre></div><p>For every other client, see <a href="/guide/clients">Connecting clients</a>.</p><h2 id="first-call" tabindex="-1">First call <a class="header-anchor" href="#first-call" aria-label="Permalink to “First call”">​</a></h2><p>Ask your assistant something that needs the library:</p><blockquote><p>What am I in the middle of?</p></blockquote><p>It should call <code>get_personalized_shelves</code> or <code>list_items_in_progress</code> and come back with titles and positions. A good second question, because it exercises the paging and projection logic:</p><blockquote><p>How many audiobooks do I own, and which is the longest?</p></blockquote><p>That is <code>list_libraries</code> followed by <code>get_library_stats</code>.</p><h2 id="check-it-by-hand" tabindex="-1">Check it by hand <a class="header-anchor" href="#check-it-by-hand" aria-label="Permalink to “Check it by hand”">​</a></h2><p>If you would rather see the protocol, the <a href="https://github.com/modelcontextprotocol/inspector" target="_blank" rel="noreferrer">MCP Inspector</a> lists the tools and lets you call them one at a time:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">AUDIOBOOKSHELF_URL</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">https://abs.example.com</span><span style="--shiki-light:#953800;--shiki-dark:#FFA657;"> \\</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">AUDIOBOOKSHELF_API_KEY=… </span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">\\</span></span>
<span class="line"><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">  npx</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> @modelcontextprotocol/inspector</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> npx</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> -y</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> audiobookshelf-mcp</span></span></code></pre></div><p><code>get_server_status</code> is the cheapest connectivity test — it needs no ids and tells you the server version.</p><h2 id="it-starts-even-when-it-is-misconfigured" tabindex="-1">It starts even when it is misconfigured <a class="header-anchor" href="#it-starts-even-when-it-is-misconfigured" aria-label="Permalink to “It starts even when it is misconfigured”">​</a></h2><p>Run it with no configuration at all and it still completes the MCP handshake and lists all 44 tools; every call then fails with the setup instructions. That is deliberate, so registry sandboxes and inspectors can enumerate the tools without credentials. It also means &quot;the tools are listed&quot; is <strong>not</strong> proof that the connection works — call <code>get_server_status</code> for that.</p><h2 id="start-read-only" tabindex="-1">Start read-only <a class="header-anchor" href="#start-read-only" aria-label="Permalink to “Start read-only”">​</a></h2><p>If you only want the questions answered and nothing changed:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">claude</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> mcp</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> add</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> audiobookshelf</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;"> \\</span></span>
<span class="line"><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;">  -e</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> AUDIOBOOKSHELF_URL=https://abs.example.com</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;"> \\</span></span>
<span class="line"><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;">  -e</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> AUDIOBOOKSHELF_API_KEY=…</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;"> \\</span></span>
<span class="line"><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;">  -e</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> AUDIOBOOKSHELF_READ_ONLY=</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;">true</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;"> \\</span></span>
<span class="line"><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;">  --</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> npx</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> -y</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> audiobookshelf-mcp</span></span></code></pre></div><p>The 15 write tools are then not registered at all, so there is nothing to refuse and nothing to talk into misbehaving.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to “Next”">​</a></h2><ul><li><a href="/guide/configuration">Configuration</a> — every environment variable</li><li><a href="/guide/faq">FAQ &amp; troubleshooting</a> — when something returns 403 or nothing</li></ul>`,31)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};